*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) === '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '2610'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) === '2' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '3410'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) !== '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) !== '2'); } }, { id: "if_totalSize", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "totalSize" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("totalSize")) > 0); } }, { id: "if_authYn", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.authYn !== "undefined" && scwin.authYn !== null ? scwin.authYn : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "authYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("authYn")) ==='Y' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "totalSize" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("totalSize")) != 0); } }, { id: "if_authYn_2", fn: function(){ return ((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) === '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '2610') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) === '2' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.psDepCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("psDepCd")) === '3410') || (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) !== '1' && ((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "pageContext.ldMktTpCd" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("ldMktTpCd")) !== '2')); } }, { id: "if_authYn_2", fn: function(){ return (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "totalSize" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("totalSize")) == 0); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
