    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf72000.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["pageCount"] != null ? rj["pageCount"] : (rj.body && rj.body["pageCount"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_62").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


